// Este nodo corre DESPUÉS de TurnoReclutador (Postgres) o directo desde If5

const trigger = $('Recibido desde Analizador').first().json;
const agenda = trigger._agenda || {};

// Si solo hay un reclutador, ya está resuelto y devolvemos la agenda directamente
if (!agenda.grupo_turno) {
    return [{
        json: agenda
    }];
}

// Si hay varios reclutadores, el índice viene de Postgres en $json
const turnoIndex = $json.ultimo_index ?? 0;

const candidatos = JSON.parse(agenda.candidatos_turno);
const asignado = candidatos[turnoIndex];

return [{
    json: {
        nombre_reclutador: asignado.nombre,
        telefono_reclutador: asignado.telefono,
        calendar_id: asignado.calendar_id,
        vacante_detectada: agenda.vacante_detectada,
        nave_candidato: agenda.nave_candidato,
        grupo_turno: agenda.grupo_turno,
        turno_index: turnoIndex
    }
}];

// 1. Obtenemos los datos desde el contexto del chat
const dbData = $('Recibido desde Analizador').first().json._candidato || {};
const chatData = $input.first().json;

// 🔮 MAGIA: Tomamos el reclutador EXACTO que ya asignó el sistema de turnos
const reclutadorAsignado = $('ResolverReclutador').first()?.json || {};

let nombreCandidato = dbData.nombre_ine || dbData.nombre_chat || "Candidato";
let telefonoCandidato = $('Recibido desde Analizador').first().json._contacto?.number || dbData.telefono || "0000000000";
let fechaCita = chatData.fecha_entrevista_detectada || "Fecha por confirmar";

// 💡 Transformar la fecha fea "2026-07-17T16:00:00" a texto bonito
if (fechaCita && fechaCita.includes("T")) {
    try {
        const [fechaParte, horaParte] = fechaCita.split('T');
        const [anio, mes, dia] = fechaParte.split('-');
        let [hora, minuto] = horaParte.split(':');

        const meses = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"];
        const nombreMes = meses[parseInt(mes, 10) - 1];

        let ampm = "AM";
        let horaInt = parseInt(hora, 10);
        if (horaInt >= 12) {
            ampm = "PM";
            if (horaInt > 12) horaInt -= 12;
        }
        if (horaInt === 0) horaInt = 12;

        fechaCita = `${parseInt(dia, 10)} de ${nombreMes} de ${anio} a las ${horaInt}:${minuto} ${ampm}`;
    } catch(e) {}
}

let naveCandidato = dbData.nave_interes || "No especificada";
let resumenIA = "Sin resumen previo disponible.";
const rawResumen = dbData.resumen_ia || "";

let vacanteDesdeResumen = "";

if (rawResumen.includes("MEMORY_UPDATE")) {
    const bloqueResumen = rawResumen.split("MEMORY_UPDATE")[1]?.split("|")?.[1]?.trim() || rawResumen;
    resumenIA = expandirResumenComprimido(bloqueResumen);
} else {
    resumenIA = rawResumen || "Sin resumen previo disponible.";

    // 💡 NUEVO: Si el resumen ya viene expandido en texto, lo extraemos de ahí
    if (resumenIA.includes("Vacante: ")) {
        const match = resumenIA.match(/Vacante:\s*([^.]+)/);
        if (match && match[1] !== 'N/D') {
            vacanteDesdeResumen = match[1].trim();
        }
    }
}

function expandirResumenComprimido(texto) {
    if (!texto) return "Sin resumen previo disponible.";
    const esFormatoComprimido = /\bN:|V:|E:|Priv:|CV:|INE:|RFC:|Cita:/.test(texto);
    if (!esFormatoComprimido) return texto;

    const get = (regex) => {
        const m = texto.match(regex);
        return m ? m[1].trim() : null;
    };

    const nombre = get(/N:([^V]*?)(?=\s+V:|$)/);
    const vacante = get(/V:([^E]*?)(?=\s+E:|$)/);
    const etapa = get(/E:([^P]*?)(?=\s+Priv:|$)/);
    const privacidad = get(/Priv:([^\s]*)/);
    const cv = get(/CV:([^\s]*)/);
    const ine = get(/INE:([^\s]*)/);
    const rfc = get(/RFC:([^\s]*)/);
    const cita = get(/Cita:([^N]*?)(?=\s+Notas:|$)/);
    const notas = get(/Notas:(.*)$/);

    // Guardamos la vacante que extrajo la IA si estaba comprimido
    if (vacante && vacante !== 'N/D') vacanteDesdeResumen = vacante;

    const siNo = (v) => v === 'S' ? 'Sí' : v === 'N' ? 'No' : (v || 'N/D');

    let partes = [];
    if (nombre) partes.push(`Nombre: ${nombre}`);
    if (vacante) partes.push(`Vacante: ${vacante}`);
    if (etapa) partes.push(`Etapa: ${etapa}`);
    if (privacidad) partes.push(`Privacidad aceptada: ${siNo(privacidad)}`);
    if (cv) partes.push(`CV recibido: ${siNo(cv)}`);
    if (ine) partes.push(`INE recibido: ${siNo(ine)}`);
    if (rfc) partes.push(`RFC recibido: ${siNo(rfc)}`);
    if (cita) partes.push(`Cita: ${cita.trim() === 'N' ? 'pendiente' : cita.trim()}`);
    if (notas) partes.push(`Notas: ${notas.trim()}`);

    return partes.length ? partes.join('. ') + '.' : texto;
}

// Limpiar espacios en blanco (ej: " ") que arruinan la vacante
let vacInteres = dbData.vacante_interes?.trim();
let vacDetectada = chatData.vacante_detectada?.trim();

// 💡 Toma la vacante detectada, o la de interés, o la del resumen de la IA
let vacanteDetectada = vacDetectada || vacInteres || vacanteDesdeResumen || "General";

// 💡 Parsear y formatear Filtros Técnicos para que se vea bonito
let ft = dbData.filtros_tecnicos;
let filtrosTecnicos = "Pendiente";
if (ft) {
    if (typeof ft === 'string') {
        try { ft = JSON.parse(ft); } catch(e){}
    }
    if (typeof ft === 'object' && ft !== null) {
        filtrosTecnicos = `Viable: ${ft.viable ? '✅ Sí' : '❌ No'}\nMotivo: ${ft.motivo || 'N/A'}`;
    } else {
        filtrosTecnicos = ft;
    }
}

// 2. Extraemos los datos del reclutador que ganó el turno
let nombreReclutador = reclutadorAsignado.nombre_reclutador || "Equipo de Reclutamiento";
let telefonoDestino = reclutadorAsignado.telefono_reclutador || "5213323379399";

// 3. ARMAR EL MENSAJE DE ÉXITO
let mensaje_alerta = `📅 *¡NUEVA ENTREVISTA AGENDADA!* \n\nHola ${nombreReclutador}, el bot acaba de cerrar una cita con éxito:\n\n👤 *Candidato:* ${nombreCandidato}\n📱 *Tel:* wa.me/${telefonoCandidato}\n💼 *Vacante:* ${vacanteDetectada}\n🏢 *Nave/Sucursal:* ${naveCandidato}\n⏰ *Fecha:* ${fechaCita}\n\n📝 *RESUMEN DEL CANDIDATO (IA):*\n${resumenIA}\n\n⚙️ *FILTROS TÉCNICOS:*\n${filtrosTecnicos}\n\n_Todos los documentos (CV, INE, RFC) ya están listos y cargados en tu Google Sheets._{https://drive.google.com/drive/folders/1teiQYm9gXvmwZfBkFLV7nsTEiljrCfpf?usp=sharing}`;

return {
    json: {
        telefono_destino: telefonoDestino.replace('@c.us', ''),
        mensaje_alerta: mensaje_alerta
    }
};

// 1. OBTENER DATOS DEL USUARIO
const dbData = $('Recibido desde Analizador').first().json._candidato || {};
const infoWhatsapp = $('Recibido desde Analizador').first().json._contacto?.[0] || {};

// 🌟 MAGIA: Tomamos el reclutador EXACTO que ya asignó el sistema de turnos
const reclutadorAsignado = $('ResolverReclutador').first()?.json || {};

// 2. BÚSQUEDA DEL MENSAJE ORIGINAL
let ultimoMensajeUsuario = "No se detectó texto";
try {
    const webhookBody = $('Recibido desde Analizador').first().json._webhook.body;
    ultimoMensajeUsuario = webhookBody.payload?.body || webhookBody.message?.body || webhookBody.body || "Mensaje multimedia o sin texto";
} catch(e) {}

// 3. RESCATAR NOMBRE Y MOTIVO DE LA IA
const rawAiResponse = $('AI Chat').first()?.json?.output || $('AI Chat').first()?.json?.text || "";
let nombreRescatadoIA = "";
let motivoRescatadoIA = "El usuario solicitó hablar con un humano.";

if (rawAiResponse.includes('HUMAN_ALERT')) {
    let fragmento = rawAiResponse.split('HUMAN_ALERT')[1].split('MEMORY_UPDATE')[0];
    let partes = fragmento.split('|').map(p => p.trim());
    if (partes.length >= 4) { nombreRescatadoIA = partes[1]; motivoRescatadoIA = partes[2]; }
    else if (partes.length === 3) { nombreRescatadoIA = partes[1]; }
}

let nombre = dbData.nombre || nombreRescatadoIA || "Candidato";
const telefono = dbData.telefono || infoWhatsapp.id?.user || "0000000000";
let vacante = dbData.vacante_interes || "General";

// 4. USAR LOS DATOS DEL NODO RESOLVER_RECLUTADOR
const nombreDestino = reclutadorAsignado.nombre_reclutador || "Equipo de Reclutamiento";
const telefonoDestino = reclutadorAsignado.telefono_reclutador || "5213323379399";

// 5. SALIDA
return {
    json: {
        telefono_destino: telefonoDestino.replace('@c.us', ''),
        nombre_candidato: nombre,          
        telefono_candidato: telefono,      
        vacante: vacante,                 
        mensaje_alerta: `🚨 *SOLICITUD DE ATENCIÓN HUMANA*\n\nHola ${nombreDestino}, este usuario pide hablar con un reclutador:\n\n👤 *${nombre}*\n📱 wa.me/${telefono}\n💼 Interés: ${vacante}\n\n💬 *Mensaje literal:* "${ultimoMensajeUsuario}"\n\n🤖 *Resumen Sofía:* _${motivoRescatadoIA}_`
    }
};

// 1. Cargar archivo
const parser = require('/home/node/virgo_files/functions/parse_special_codes.js');

// 2. Obtener datos de entrada
const item = $input.first();
const aiResponse = item.json.output || item.json.text || "";

// 3. Preparar contexto
const webhookData = $('Recibido desde Analizador').first().json._webhook.body.payload;
const context = { 
  phone: webhookData.from,
  executionId: $execution.id 
};

// 4. Ejecutar parser externo
const result = parser(aiResponse, context);

// ---------------------------------------------------------
// 5. PARCHES Y ETIQUETAS SECRETAS
// ---------------------------------------------------------

// Limpieza inicial de MEMORY_UPDATE
if (result.message_to_user) {
  result.message_to_user = result.message_to_user.split('MEMORY_UPDATE')[0].trim();
}

// ACTUALIZAR_NOMBRE
if (aiResponse.includes('ACTUALIZAR_NOMBRE')) {
  const line = aiResponse.split('\n').find(l => l.includes('ACTUALIZAR_NOMBRE'));
  if (line) {
    const parts = line.split('|').map(s => s.trim());
    if (parts.length >= 2) result.nombre_detectado = parts[1];
  }
}

// ACTUALIZAR_VACANTE
if (aiResponse.includes('ACTUALIZAR_VACANTE')) {
  const line = aiResponse.split('\n').find(l => l.includes('ACTUALIZAR_VACANTE'));
  if (line) {
    const parts = line.split('|').map(s => s.trim());
    if (parts.length >= 2) result.vacante_detectada = parts[1].toUpperCase();
  }
}
// ACTUALIZAR_NAVE
if (aiResponse.includes('ACTUALIZAR_NAVE')) {
  const line = aiResponse.split('\n').find(l => l.includes('ACTUALIZAR_NAVE'));
  if (line) {
    const parts = line.split('|').map(s => s.trim());
    if (parts.length >= 2) result.nave_detectada = parts[1].toUpperCase();
  }
}

// PRIVACIDAD_ACEPTADA
if (aiResponse.includes('PRIVACIDAD_ACEPTADA')) {
  result.acepto_privacidad = true;
}

// CITA_CANCELADA
if (aiResponse.includes('CITA_CANCELADA')) {
  result.cita_cancelada = true;
}

// CITA_CONFIRMADA
if (aiResponse.includes('CITA_CONFIRMADA')) {
  const match = aiResponse.match(/CITA_CONFIRMADA[\s:|]*(.*?)([|\n]|$)/i);
  if (match?.[1]) {
    result.fecha_entrevista_detectada = match[1].replace(/\|/g, '').trim();
  }
}

// HUMAN_ALERT
if (aiResponse.includes('HUMAN_ALERT')) {
    const mensajeHumanoDefault =
        "Gracias por explicarme 😊 Voy a compartir tu caso con el equipo de reclutamiento para que puedan revisarlo y darte seguimiento por este medio.";

    let fragmento = aiResponse
        .split(/HUMAN_ALERT/i)[1]
        ?.split(/MEMORY_UPDATE/i)[0] || "";

    fragmento = fragmento.trim();
    fragmento = fragmento.replace(/^\s*\|\s*/, "").trim();
    const partesRaw = fragmento.split("|").map(p => p.trim());

    let nombre = "";
    let resumen = "";
    let mensajeVisible = "";
    const primerCampo = partesRaw[0] || "";
    const primerCampoPareceResumen =
        /candidato|documento|constancia|rfc|ine|cv|solicit|agend|conflict|no cuenta|no tiene/i.test(primerCampo);

    if (partesRaw.length >= 3 && !primerCampoPareceResumen) {
        nombre = partesRaw[0];
        resumen = partesRaw[1];
        mensajeVisible = partesRaw.slice(2).join(" | ").trim();
    } else if (partesRaw.length >= 2 && primerCampoPareceResumen) {
        nombre = $('Recibido desde Analizador').first().json._candidato?.nombre_chat
              || $('Recibido desde Analizador').first().json._candidato?.nombre_ine
              || $('Recibido desde Analizador').first().json._candidato?.nombre_solicitud
              || "Candidato";
        resumen = partesRaw[0];
        mensajeVisible = partesRaw.slice(1).join(" | ").trim();
    } else if (partesRaw.length >= 2) {
        nombre = partesRaw[0];
        resumen = partesRaw[1];
        mensajeVisible = mensajeHumanoDefault;
    } else {
        nombre = $('Recibido desde Analizador').first().json._candidato?.nombre_chat
              || $('Recibido desde Analizador').first().json._candidato?.nombre_ine
              || $('Recibido desde Analizador').first().json._candidato?.nombre_solicitud
              || "Candidato";
        resumen = "El candidato solicitó apoyo de reclutamiento humano.";
        mensajeVisible = mensajeHumanoDefault;
    }

    if (
        !mensajeVisible ||
        /^el candidato/i.test(mensajeVisible) ||
        /impidiendo el agendamiento/i.test(mensajeVisible) ||
        /solicitó escalamiento/i.test(mensajeVisible)
    ) {
        mensajeVisible = mensajeHumanoDefault;
    }

    result.human_alert_nombre = nombre.trim();
    result.human_alert_resumen = resumen.trim();
    result.message_to_user = mensajeVisible.trim();
}

// CV_MANUAL
if (aiResponse.includes('CV_MANUAL')) {
  const match = aiResponse.match(/CV_MANUAL[\s:|]*(\{[\s\S]*?\})/i);
  if (match?.[1]) {
    try {
      const jsonLimpio = match[1]
        .replace(/```json/gi, '')
        .replace(/```/g, '')
        .replace(/[\n\r\t]/g, ' ')
        .trim();
      const cvData = JSON.parse(jsonLimpio);
      result.experiencia_manual = cvData.experiencia;
      result.vacante_manual = cvData.vacante;
      result.datos_cv_manual = cvData;
      result.es_cv_manual = true;
      if (cvData.nombre && cvData.nombre !== "Desconocido") {
        result.nombre_detectado = cvData.nombre;
      }
    } catch (e) {
      result.datos_cv_manual = { error: "La IA formateó mal el JSON", experiencia: "Candidato llenó solicitud manual por chat." };
      result.es_cv_manual = true;
    }
  }
}

// RESPUESTAS_FILTRO
if (aiResponse.includes('RESPUESTAS_FILTRO')) {
  const match = aiResponse.match(/RESPUESTAS_FILTRO[\s:|]*([\s\S]*?)(?=\n[A-Z_]+\s*\||$)/i);
  if (match?.[1]) {
    result.respuestas_filtro_detectadas = match[1].replace(/\|/g, '').trim();
  }
}

// ENVIAR_UBICACION
if (aiResponse.includes('ENVIAR_UBICACION')) {
  result.enviar_ubicacion = true;
}

// ---------------------------------------------------------
// 6. LIMPIEZA VISUAL PROFUNDA
// ---------------------------------------------------------

if (result.message_to_user) {
  result.message_to_user = result.message_to_user
    .replace(/ACTUALIZAR_NOMBRE\s*\|\s*[^|\n]+(?:\||)/gi, '')
    .replace(/ACTUALIZAR_VACANTE\s*\|\s*[^|\n]+(?:\||)/gi, '')
    .replace(/ACTUALIZAR_NAVE\s*\|\s*[^|\n]+(?:\||)/gi, '')
    .replace(/^\s*\[REQUISITO EXCLUSIVO:\s*[^\]]+\]\s*$/gim, '')
    .replace(/\s*\[REQUISITO EXCLUSIVO:\s*[^\]]+\]\s*/gi, '')
    .replace(/^\s*\[(CONTROL_INTERNO|PERFIL|CONDICIONES_OPERATIVAS|REQUISITO_FISICO):[^\]]+\]\s*$/gim, '')
    .replace(/\s*\[(CONTROL_INTERNO|PERFIL|CONDICIONES_OPERATIVAS|REQUISITO_FISICO):[^\]]+\]\s*/gi, '')
    .replace(/PRIVACIDAD_ACEPTADA\s*\|?/gi, '')
    .replace(/CITA_CONFIRMADA[\s:|]*(.*?)([|\n]|$)/gi, '')
    .replace(/CITA_CANCELADA[\s:|]*(.*?)([|\n]|$)/gi, '')
    .replace(/ENVIAR_UBICACION[\s:|]*(.*?)([|\n]|$)/gi, '')
    .replace(/RESPUESTAS_FILTRO[\s:|]*([\s\S]*?)(?=\n[A-Z_]+\s*\||$)/gi, '')
    .replace(/CV_MANUAL[\s:|]*\{[\s\S]*?\}/gi, '')
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  if (result.fecha_entrevista_detectada) {
    result.message_to_user = result.message_to_user
      .replace(result.fecha_entrevista_detectada, '')
      .replace(/\|/g, '')
      .trim();
  }

  if (
      /^el candidato/i.test(result.message_to_user) ||
      result.message_to_user.includes("impidiendo el agendamiento") ||
      result.message_to_user.includes("Solicitó escalamiento") ||
      result.message_to_user.includes("solicitó escalamiento")
  ) {
      result.message_to_user =
          "Gracias por explicarme 😊 Voy a compartir tu caso con el equipo de reclutamiento para que puedan revisarlo y darte seguimiento por este medio.";
  }

    if (result.message_to_user.includes("|")) {
      const partes = result.message_to_user.split("|").map(p => p.trim()).filter(Boolean);
      result.message_to_user = partes[partes.length - 1] ||
          "Gracias por explicarme 😊 Voy a compartir tu caso con el equipo de reclutamiento para que puedan revisarlo y darte seguimiento por este medio.";
  }


  result.message_to_user = result.message_to_user
    .replace(/^[|\s]+/, '')
    .trim();
}

if (!result.message_to_user || result.message_to_user.trim() === "") {
  result.message_to_user = "Gracias por tu mensaje 😊 Permíteme revisar la información para poder ayudarte mejor.";
}

// ---------------------------------------------------------
// 7. SPLIT DE MENSAJES
// ---------------------------------------------------------

let mensajes = [result.message_to_user];
if (result.message_to_user.includes('[SPLIT]')) {
  mensajes = result.message_to_user.split(/\[SPLIT\]/i).map(m => m.trim()).filter(m => m !== "");
}

let output = [];
for (let msg of mensajes) {
  let itemCopia = JSON.parse(JSON.stringify(result));
  itemCopia.message_to_user = msg;
  output.push({ json: itemCopia });
}


// 8. AÑADIR MENÚ CADA 3 MENSAJES
let mensajes_enviados = $('Recibido desde Analizador').first().json._candidato?.mensajes_bot_enviados || 0;
if (mensajes_enviados % 3 === 0 && output.length > 0) {
    output[output.length - 1].json.message_to_user += '\n\n_(Escribe "Menú" para volver al menú principal o "Cambiar sucursal" para cambiar de nave)_';
}

return output;

